473	static void _epic_execute_drawing(lv_draw_sifli_epic_unit_t * u)
474	{
475	    lv_draw_task_t * task = u->task_act;
476	    lv_layer_t * layer = ((lv_draw_unit_t *)u)->target_layer;
477	
478	    if(layer && layer->draw_buf) {
479	        lv_area_t draw_area;
480	
481	        if(_lv_area_intersect(&draw_area, &task->_real_area, &task->clip_area)) {
482	            lv_area_move(&draw_area, -layer->buf_area.x1, -layer->buf_area.y1);
483	            lv_draw_buf_flush_cache(layer->draw_buf, &draw_area);
484	        }
485	    }
486	
487	    /* Execute based on task type */
488	    switch(task->type) {
489	        case LV_DRAW_TASK_TYPE_BORDER:
490	            lv_draw_sifli_epic_border(task);
491	            break;
492	
493	        case LV_DRAW_TASK_TYPE_LABEL:
494	            lv_draw_sifli_epic_label(task);
495	            break;
496	
497	        case LV_DRAW_TASK_TYPE_FILL:
498	            lv_draw_sifli_epic_fill(task);
499	            break;
500	
501	        case LV_DRAW_TASK_TYPE_IMAGE:
502	            lv_draw_sifli_epic_img(task);
503	            break;
504	
505	        case LV_DRAW_TASK_TYPE_LAYER:
506	            lv_draw_sifli_epic_layer(task);
507	            break;
508	
509	        default:
510	            break;
511	    }
512	
513	    if(layer && layer->draw_buf) {
514	        lv_area_t draw_area;
515	
516	        if(_lv_area_intersect(&draw_area, &task->_real_area, &task->clip_area)) {
517	            lv_area_move(&draw_area, -layer->buf_area.x1, -layer->buf_area.y1);
518	            lv_draw_buf_invalidate_cache(layer->draw_buf, &draw_area);
519	        }
520	    }
521	
